<script setup lang="ts">
import { useI18n } from "vue-i18n";
import {onBeforeUnmount,onMounted,ref} from "vue";
import {useAuth} from "@papilio/auth";
import {item,request,query,type Page,type CustomerTier,type LoyaltyPolicyRead,type LoyaltyPolicy} from "@papilio/api";
import Modal from "@papilio/ui/Modal.vue";
import {faNumber,toman} from "@papilio/ui";
const { t } = useI18n();
const auth=useAuth(),rows=ref<CustomerTier[]>([]),page=ref(1),pages=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(""),notice=ref("");
const savedPolicy=ref<LoyaltyPolicyRead|null>(null),policyDraft=ref<LoyaltyPolicy|null>(null),overrideJson=ref("{}"),policyOpen=ref(false),tierOpen=ref(false),selected=ref<CustomerTier|null>(null);
const minimumPaymentToman=ref(0);
const draft=ref({code:"",title:"",minimum_bytes:0,discount_bps:0,is_enabled:true});let alive=true,version=0;
const booleans=[['enabled','enable'],['renewal_tier_discount','renewalDiscounts'],['notify_tier_changes','notifyTiers'],['notify_discounts','notifyDiscounts']] as const;
function fail(cause:unknown):void{error.value=cause instanceof Error?cause.message:t("loyalty.operationFailed");}
async function load():Promise<void>{const stamp=++version;loading.value=true;error.value="";try{const [tiers,policy]=await Promise.all([request<Page<CustomerTier>>(`/v1/admin/loyalty/tiers?${query({page:page.value})}`),item<LoyaltyPolicyRead>("/v1/admin/loyalty/policy")]);if(!alive||stamp!==version)return;rows.value=tiers.data;pages.value=tiers.meta.pager?.total_pages??1;total.value=tiers.meta.pager?.total_items??0;if(!policyOpen.value)savedPolicy.value=policy;}catch(cause){if(alive&&stamp===version)fail(cause);}finally{if(stamp===version)loading.value=false;}}
async function initialize():Promise<void>{busy.value=true;error.value="";try{await item<LoyaltyPolicyRead>("/v1/admin/loyalty/initialize","POST");notice.value=t("loyalty.seeded");await load();}catch(cause){fail(cause);}finally{busy.value=false;}}
function edit(row:CustomerTier|null):void{selected.value=row;draft.value=row?{code:row.code,title:row.title,minimum_bytes:row.minimum_bytes,discount_bps:row.discount_bps,is_enabled:row.is_enabled}:{code:"",title:"",minimum_bytes:0,discount_bps:0,is_enabled:true};error.value="";tierOpen.value=true;}
async function saveTier():Promise<void>{busy.value=true;error.value="";try{if(!Number.isSafeInteger(draft.value.minimum_bytes)||!Number.isSafeInteger(draft.value.discount_bps))throw Error(t("loyalty.invalidTierNumbers"));await item<CustomerTier>(selected.value?`/v1/admin/loyalty/tiers/${selected.value.id}`:"/v1/admin/loyalty/tiers",selected.value?"PUT":"POST",{...draft.value,expected_revision:selected.value?.revision??null});tierOpen.value=false;await load();}catch(cause){fail(cause);}finally{busy.value=false;}}
function editPolicy():void{if(!savedPolicy.value)return;policyDraft.value={...savedPolicy.value.values,unlimited_plan_bytes:{...savedPolicy.value.values.unlimited_plan_bytes}};overrideJson.value=JSON.stringify(policyDraft.value.unlimited_plan_bytes,null,2);minimumPaymentToman.value=policyDraft.value.minimum_qualifying_rial/10;error.value="";policyOpen.value=true;}
async function savePolicy():Promise<void>{if(!policyDraft.value||!savedPolicy.value)return;busy.value=true;error.value="";try{const overrides:unknown=JSON.parse(overrideJson.value);if(!overrides||typeof overrides!=="object"||Array.isArray(overrides)||Object.entries(overrides).some(([id,value])=>!/^\d+$/.test(id)||Number(id)<=0||typeof value!=="number"||!Number.isSafeInteger(value)||value<0))throw Error(t("loyalty.invalidOverrides"));const result=await item<LoyaltyPolicyRead>("/v1/admin/loyalty/policy","PUT",{expected_revision:savedPolicy.value.revision,values:{...policyDraft.value,minimum_qualifying_rial:Math.round(minimumPaymentToman.value*10),unlimited_plan_bytes:overrides}});savedPolicy.value=result;policyOpen.value=false;notice.value=t("loyalty.saved");}catch(cause){fail(cause);}finally{busy.value=false;}}
onMounted(()=>void load());onBeforeUnmount(()=>{alive=false;version++;});
</script>
<template>
 <header class="page-head"><div><p class="eyebrow">{{ t('loyalty.eyebrow') }}</p><h1>{{ t('loyalty.title') }}</h1><p class="subtitle">{{ t('loyalty.description') }}</p></div><div class="toolbar"><button v-if="auth.can('catalog','create')" class="btn secondary" :disabled="busy" @click="initialize">{{t("loyalty.seed")}}</button><button v-if="auth.can('catalog','create')" class="btn" @click="edit(null)">{{t("loyalty.createTier")}}</button></div></header>
 <p v-if="error&&!tierOpen&&!policyOpen" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
 <section class="card card-pad"><div class="toolbar"><h2>{{t("loyalty.policyTitle")}}</h2><button class="btn secondary" :disabled="loading" @click="load">{{t("loyalty.refresh")}}</button><button v-if="auth.can('catalog','update')&&savedPolicy" class="btn" @click="editPolicy">{{t("loyalty.editPolicy")}}</button></div><template v-if="savedPolicy"><p>{{savedPolicy.values.enabled?t('loyalty.enabled'):t('loyalty.disabled')}} · Revision {{faNumber(savedPolicy.revision)}} · {{savedPolicy.values.tier_basis==='net_purchases'?t('loyalty.netQuota'):t('loyalty.lifetimeQuota')}}</p><p>{{t("loyalty.firstPurchase")}}: {{faNumber(savedPolicy.values.first_purchase_discount_bps/100)}}% · {{t("loyalty.maximumDiscount")}}: {{faNumber(savedPolicy.values.maximum_discount_bps/100)}}% · {{t("loyalty.combination")}}: {{savedPolicy.values.combination_mode}}</p><p>Unlimited plans: {{savedPolicy.values.unlimited_credit_mode==='exclude'?t('loyalty.noQuotaCredit'):t('loyalty.gibEquivalent',{value:faNumber(savedPolicy.values.unlimited_equivalent_bytes/1024**3)})}} · {{t("loyalty.minimumPayment")}}: {{toman(savedPolicy.values.minimum_qualifying_rial)}}</p></template></section>
 <section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("loyalty.tier")}}</th><th>{{t("loyalty.minimumQuota")}}</th><th>{{t("loyalty.discount")}}</th><th>{{t("loyalty.status")}}</th><th>{{t("loyalty.actions")}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.title}}</strong><br/>{{row.code}}</td><td>{{faNumber(row.minimum_bytes/1024**3)}} GiB</td><td>{{faNumber(row.discount_bps/100)}}%</td><td><span class="badge" :class="row.is_enabled?'success':'warning'">{{row.is_enabled?t('loyalty.enabled'):t('loyalty.disabled')}}</span></td><td><button v-if="auth.can('catalog','update')" class="btn small secondary" @click="edit(row)">{{t("loyalty.editTier",{title:row.title})}}</button></td></tr></tbody></table><p v-if="loading" class="empty">{{t("loyalty.loadingTiers")}}</p><p v-else-if="!error&&!rows.length" class="empty">{{t("loyalty.emptyTiers")}}</p></div><div class="pager"><button :disabled="loading||page<=1" @click="page--;load()">‹</button><span>{{t("loyalty.pageCount",{page:faNumber(page),total:faNumber(total)})}}</span><button :disabled="loading||page>=pages" @click="page++;load()">›</button></div></section>
 <Modal v-model="tierOpen" :title="selected?t('loyalty.editTier',{title:selected.title}):t('loyalty.createTier')" :busy="busy"><form class="form-grid" @submit.prevent="saveTier"><p v-if="error" class="message error" role="alert">{{error}}</p><label class="field"><span>{{t("loyalty.code")}}</span><input v-model="draft.code" required pattern="[a-z0-9_-]+" minlength="2" maxlength="32"/></label><label class="field"><span>{{t("loyalty.titleField")}}</span><input v-model="draft.title" required minlength="2" maxlength="100"/></label><label class="field"><span>{{t("loyalty.minimumQuotaBytes")}}</span><input v-model.number="draft.minimum_bytes" type="number" min="0" step="1" required/></label><label class="field"><span>{{t("loyalty.discountBps")}}</span><input v-model.number="draft.discount_bps" type="number" min="0" max="10000" step="1" required/></label><label class="check-row"><input v-model="draft.is_enabled" type="checkbox"/>{{t("loyalty.enabled")}}</label><p v-if="selected">{{t("loyalty.editingRevision",{revision:faNumber(selected.revision)})}}</p><button class="btn" :disabled="busy">{{t("loyalty.saveTier")}}</button></form></Modal>
 <Modal v-model="policyOpen" :title="t('loyalty.rulesTitle')" :busy="busy" wide><form v-if="policyDraft" class="form-grid" @submit.prevent="savePolicy"><p v-if="error" class="message error" role="alert">{{error}}</p><p>{{t("loyalty.editingPolicyRevision",{revision:faNumber(savedPolicy?.revision??0)})}}</p><div class="form-grid three"><label v-for="[field,label] in booleans" :key="field" class="check-row"><input v-model="policyDraft[field]" type="checkbox"/>{{t(`loyalty.${label}`)}}</label><label class="field"><span>{{t("loyalty.tierBasis")}}</span><select v-model="policyDraft.tier_basis"><option value="net_purchases">{{t("loyalty.netPurchases")}}</option><option value="lifetime_purchases">{{t("loyalty.lifetimePurchases")}}</option></select></label><label class="field"><span>{{t("loyalty.discountCombination")}}</span><select v-model="policyDraft.combination_mode"><option value="best">{{t("loyalty.bestSingle")}}</option><option value="additive">{{t("loyalty.addDiscounts")}}</option><option value="sequential">{{t("loyalty.sequential")}}</option></select></label><label class="field"><span>{{t("loyalty.firstPurchaseEligibility")}}</span><select v-model="policyDraft.first_purchase_basis"><option value="net_purchases">Net purchases after refunds</option><option value="lifetime_purchases">{{t("loyalty.noPreviousPurchase")}}</option></select></label><label class="field"><span>{{t("loyalty.firstPurchaseBps")}}</span><input v-model.number="policyDraft.first_purchase_discount_bps" type="number" min="0" max="10000" required/></label><label class="field"><span>{{t("loyalty.maximumDiscountBps")}}</span><input v-model.number="policyDraft.maximum_discount_bps" type="number" min="0" max="10000" required/></label><label class="field"><span>{{t("loyalty.minimumQualifyingToman")}}</span><input v-model.number="minimumPaymentToman" type="number" min="0" step="0.1" required/></label><label class="field"><span>{{t("loyalty.unlimitedCredit")}}</span><select v-model="policyDraft.unlimited_credit_mode"><option value="exclude">{{t("loyalty.excludeUnlimited")}}</option><option value="equivalent">{{t("loyalty.equivalentQuota")}}</option></select></label><label class="field"><span>{{t("loyalty.unlimitedEquivalentBytes")}}</span><input v-model.number="policyDraft.unlimited_equivalent_bytes" type="number" min="0" step="1" required/></label></div><label class="field"><span>{{t("loyalty.unlimitedMap")}}</span><textarea v-model="overrideJson" rows="5" spellcheck="false"/></label><p class="subtitle">{{t("loyalty.policyHint")}}</p><button class="btn" :disabled="busy">{{t("loyalty.savePolicy")}}</button></form></Modal>
</template>
